<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Policy Checker Online','description'=>'Check a password against common length and character requirements.','url'=>'https://smarttoolz.in/tools/password-policy-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">PASSWORD POLICY</span><h1>Password Policy Checker</h1><p>Check whether a password meets common security requirements.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Password<input id="p" type="password"></label><button id="go" class="tool-btn">Check Policy</button><p id="out" style="line-height:1.8;font-weight:700"></p></div></section></main><script>(()=>{const p=document.getElementById('p'),o=document.getElementById('out');document.getElementById('go').onclick=()=>{let s=p.value,r=[`${s.length>=8?'✓':'✗'} At least 8 characters`,`${/[A-Z]/.test(s)?'✓':'✗'} Uppercase letter`,`${/[a-z]/.test(s)?'✓':'✗'} Lowercase letter`,`${/\d/.test(s)?'✓':'✗'} Number`,`${/[^A-Za-z0-9]/.test(s)?'✓':'✗'} Special character`];o.innerHTML=r.join('<br>')}})();</script><?php smarttoolz_tool_page_end(); ?>